"""Bounded objective-descent basin search for one piecewise-smooth FV case.

This only proposes a nearby candidate. Exact stationarity and response use
the original objective/Hessian in separate gates after the search.
"""
from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
import hashlib
import json
import math
import time
from typing import Any

import torch
from torch import Tensor


@dataclass(frozen=True)
class BasinSearchResult:
    status: str
    control: Tensor
    objective: float
    gradient_max: float
    accepted_steps: int
    trial_evaluations: int
    branch_changes: int
    history: list[dict[str, Any]]


def _branch_key(signature: dict[str, Any]) -> str:
    if "choices" not in signature or "face_signs" not in signature:
        raise ValueError("basin branch requires choices and face_signs")
    return json.dumps(
        {name: signature[name] for name in ("choices", "face_signs")},
        sort_keys=True, separators=(",", ":"), allow_nan=False,
    )


def _evaluate(
    objective: Callable[[Tensor, Tensor], Tensor],
    gradient: Callable[[Tensor, Tensor], Tensor],
    control: Tensor,
    parameters: Tensor,
) -> tuple[float, Tensor, float]:
    value = objective(control, parameters)
    g = gradient(control, parameters)
    if (not isinstance(value, Tensor) or value.ndim != 0
            or not isinstance(g, Tensor) or g.shape != control.shape
            or g.dtype != control.dtype or g.device != control.device
            or not bool(torch.isfinite(value)) or not bool(torch.isfinite(g).all())):
        raise ValueError("basin objective or control gradient is invalid")
    gradient_norm = float(torch.linalg.vector_norm(g))
    if not math.isfinite(gradient_norm):
        raise ValueError("basin control gradient norm is nonfinite")
    return float(value), g.detach(), float(g.abs().max())


def _direction(
    gradient: Tensor, pairs: list[tuple[Tensor, Tensor, float]],
) -> tuple[Tensor, str | None]:
    q = gradient.clone()
    alphas: list[float] = []
    fallback: str | None = None
    for step, change, inverse_curvature in reversed(pairs):
        alpha = inverse_curvature * float(torch.dot(step, q))
        if not math.isfinite(alpha):
            fallback = "nonfinite_two_loop_alpha"
            break
        alphas.append(alpha)
        q = q - alpha * change
        if not bool(torch.isfinite(q).all()):
            fallback = "nonfinite_two_loop_vector"
            break
    gamma = 1.0
    if pairs and fallback is None:
        step, change, _ = pairs[-1]
        numerator = float(torch.dot(step, change))
        denominator = float(torch.dot(change, change))
        if (not math.isfinite(numerator) or not math.isfinite(denominator)
                or denominator <= 0):
            fallback = "nonfinite_two_loop_scale"
        else:
            gamma = numerator / denominator
        if fallback is None and not math.isfinite(gamma):
            fallback = "nonfinite_two_loop_scale"
        if fallback is None:
            gamma = min(max(gamma, 1e-6), 1e6)
    result = gamma * q if fallback is None else gradient
    if fallback is None:
        for (step, change, inverse_curvature), alpha in zip(pairs, reversed(alphas)):
            beta = inverse_curvature * float(torch.dot(change, result))
            if not math.isfinite(beta):
                fallback = "nonfinite_two_loop_beta"
                break
            result = result + step * (alpha - beta)
            if not bool(torch.isfinite(result).all()):
                fallback = "nonfinite_two_loop_vector"
                break
    direction = -result if fallback is None else -gradient
    gnorm = float(torch.linalg.vector_norm(gradient))
    dnorm = float(torch.linalg.vector_norm(direction))
    slope = float(torch.dot(gradient, direction))
    if (fallback is not None or not math.isfinite(dnorm) or dnorm == 0.0
            or not math.isfinite(slope)
            or slope >= -1e-12 * gnorm * dnorm):
        pairs.clear()
        direction = -gradient
        dnorm = gnorm
        fallback = fallback or "non_descent_lbfgs"
    if not math.isfinite(dnorm) or dnorm == 0.0:
        raise ValueError("basin steepest descent norm is invalid")
    if dnorm > 1.0:
        direction = direction / dnorm
    if not bool(torch.isfinite(direction).all()):
        raise ValueError("basin search direction is nonfinite")
    return direction, fallback


def search_basin(
    objective: Callable[[Tensor, Tensor], Tensor],
    control: Tensor,
    parameters: Tensor,
    branch_check: Callable[[Tensor, Tensor], tuple[dict[str, Any], str]],
    *,
    checkpoint: Callable[[dict[str, Any]], None] | None = None,
    max_steps: int = 100,
    max_backtracks: int = 16,
    max_trials: int = 1600,
    memory: int = 10,
    phase_seconds: float = 600.0,
    handoff_gradient_max: float = 1e-4,
) -> BasinSearchResult:
    """Search on the unchanged objective; accepted controls must be strict points.

    Actual objective decrease is checked even if a step crosses a minmod
    selector surface. Such a crossing resets curvature history and is not a
    branch-preserving-path certificate.
    """
    if (not isinstance(control, Tensor) or not isinstance(parameters, Tensor)
            or control.ndim != 1 or parameters.ndim != 1
            or control.dtype != torch.float64 or parameters.dtype != torch.float64
            or control.device.type != "cpu" or parameters.device.type != "cpu"
            or not bool(torch.isfinite(control).all())
            or not bool(torch.isfinite(parameters).all())):
        raise ValueError("basin search requires finite CPU FP64 vectors")
    if (max_steps < 1 or max_backtracks < 1 or max_trials < 1 or memory < 1
            or phase_seconds <= 0 or handoff_gradient_max <= 0):
        raise ValueError("basin search limits must be positive")
    started = time.monotonic()
    current = control.detach().clone()
    p = parameters.detach().clone()
    gradient = torch.func.grad(objective, argnums=0)
    signature, _ = branch_check(current, p)
    current_branch = _branch_key(signature)
    value, g, gmax = _evaluate(objective, gradient, current, p)
    history: list[dict[str, Any]] = []
    pairs: list[tuple[Tensor, Tensor, float]] = []
    accepted = trials = changes = 0

    def finish(status: str) -> BasinSearchResult:
        return BasinSearchResult(status, current, value, gmax, accepted, trials, changes, history)

    if time.monotonic() - started >= phase_seconds:
        return finish("time_budget")
    if gmax <= handoff_gradient_max:
        return finish("candidate")
    for iteration in range(1, max_steps + 1):
        if time.monotonic() - started >= phase_seconds:
            return finish("time_budget")
        direction, fallback = _direction(g, pairs)
        if time.monotonic() - started >= phase_seconds:
            return finish("time_budget")
        slope = float(torch.dot(g, direction))
        if not math.isfinite(slope) or slope >= 0:
            return finish("no_descent_direction")
        accepted_trial = False
        for backtrack in range(max_backtracks):
            if time.monotonic() - started >= phase_seconds:
                return finish("time_budget")
            if trials >= max_trials:
                return finish("trial_budget")
            trials += 1
            alpha = 0.5**backtrack
            candidate = current + alpha * direction
            record: dict[str, Any] = {
                "iteration": iteration, "backtrack": backtrack, "alpha": alpha,
                "slope": slope, "status": "trial", "direction_fallback": fallback,
                "control_sha256": hashlib.sha256(
                    candidate.detach().contiguous().cpu().numpy().tobytes()
                ).hexdigest(),
            }
            if not bool(torch.isfinite(candidate).all()):
                record["status"] = "nonfinite_control"
            else:
                trial_phase = "branch"
                try:
                    candidate_signature, _ = branch_check(candidate, p)
                    candidate_branch = _branch_key(candidate_signature)
                    record.update(
                        branch_key=candidate_branch,
                        signature_sha256=hashlib.sha256(candidate_branch.encode()).hexdigest(),
                        euler_stages=candidate_signature.get("euler_stages"),
                        minimum_scaled_slope_margin=candidate_signature.get(
                            "minimum_scaled_slope_margin"
                        ),
                        minimum_scaled_face_flux_margin=candidate_signature.get(
                            "minimum_scaled_face_flux_margin"
                        ),
                    )
                    trial_phase = "evaluation"
                    new_value, new_g, new_gmax = _evaluate(
                        objective, gradient, candidate, p
                    )
                    if time.monotonic() - started >= phase_seconds:
                        record["status"] = "time_budget"
                        history.append(record)
                        if checkpoint is not None:
                            checkpoint(record)
                        return finish("time_budget")
                    reduction = value - new_value
                    floor = 64 * torch.finfo(torch.float64).eps * max(
                        abs(value), torch.finfo(torch.float64).tiny
                    )
                    armijo_bound = value + 1e-4 * alpha * slope
                    if not math.isfinite(reduction) or not math.isfinite(armijo_bound):
                        record.update(status="nonfinite_reduction_arithmetic",
                                      objective=new_value)
                    elif (new_value <= armijo_bound
                            and reduction > floor):
                        step = (candidate - current).detach()
                        change = (new_g - g).detach()
                        switched = candidate_branch != current_branch
                        if switched:
                            pairs.clear()
                            changes += 1
                        else:
                            curvature = float(torch.dot(step, change))
                            scale = float(torch.linalg.vector_norm(step) *
                                          torch.linalg.vector_norm(change))
                            if (math.isfinite(curvature) and math.isfinite(scale)
                                    and curvature > 1e-10 * scale):
                                inverse_curvature = 1.0 / curvature
                                if math.isfinite(inverse_curvature):
                                    pairs.append((step, change, inverse_curvature))
                                    if len(pairs) > memory:
                                        pairs.pop(0)
                                else:
                                    pairs.clear()
                            else:
                                pairs.clear()
                        current, g, value, gmax = candidate.detach(), new_g, new_value, new_gmax
                        current_branch = candidate_branch
                        accepted += 1
                        record.update(status="accepted", objective=value,
                                      gradient_max=gmax, branch_changed=switched,
                                      branch_key=current_branch, reduction=reduction,
                                      control=current.detach().tolist(),
                                      gradient=g.detach().tolist())
                        accepted_trial = True
                    else:
                        record.update(
                            status=("roundoff_refusal" if new_value <= armijo_bound
                                    else "armijo_refusal"),
                            objective=new_value, reduction=reduction,
                        )
                except ValueError as error:
                    record.update(status=f"{trial_phase}_refused", reason=str(error))
                except RuntimeError as error:
                    record.update(status="candidate_runtime_error", reason=str(error))
                    history.append(record)
                    if checkpoint is not None:
                        checkpoint(record)
                    raise
            history.append(record)
            if checkpoint is not None:
                checkpoint(record)
            if accepted_trial:
                break
        if time.monotonic() - started >= phase_seconds:
            return finish("time_budget")
        if not accepted_trial:
            return finish("line_search_refused")
        if gmax <= handoff_gradient_max:
            return finish("candidate")
    return finish("step_budget")

source_snapshots.examples/weather_scenarios/fv_point_pair:
"""Audit one-sided interval normals at the pinned paired-face tangent point."""
from __future__ import annotations

import argparse
from decimal import Decimal
from fractions import Fraction
import hashlib
import json
import platform
from pathlib import Path
from typing import Any

import mpmath

from examples.weather_scenarios import fv_point_paired_face_normal_reference as reference

ROOT = Path(__file__).resolve().parents[2]
EVIDENCE = ROOT / "graphify-out/fv-root-cause-20260919"
INPUT, PLAN, PAIRED = (EVIDENCE / "R2_POINT_PAIRED_FACE_NORMAL_INPUT_20261003.json",
                       EVIDENCE / "R2_POINT_PAIRED_FACE_NORMAL_PLAN_20261003.md",
                       EVIDENCE / "point_paired_face_stationarity_attempt1/stationarity.json")
INPUT_SHA = "dd9caee732c44ed0961cadd5265005ddfa95bbd5b1d61abab2a08ff6d24a4320"
PLAN_SHA = "db6e7b247b01c70eca72113e92b78fced46df3135500e8f52c06485286a2e9b2"
PAIRED_SHA = "d38d1cec4550a6347ceb14db23395679a59a7cad89f09096ec7185f984f6a8cf"
SOURCE_PATHS = ("examples/weather_scenarios/fv_point_paired_face_normal_reference.py", "examples/weather_scenarios/fv_active_face_normal_reference.py",
                "examples/weather_scenarios/fv_slice_precision_reference.py", "examples/weather_scenarios/fv_point_paired_face_normal_probe.py",
                "tests/test_fv_point_paired_face_normal_probe.py")
UnsupportedNormal = reference.NormalReferenceRefusal

def sha(path: Path) -> str: return hashlib.sha256(path.read_bytes()).hexdigest()

def _flat(value: Any) -> list[Any]:
    if not isinstance(value,list): raise ValueError("trace field must be a list")
    return [v for row in value for v in row] if value and isinstance(value[0],list) else value
def _choice(row: dict[str, Any], axis: str) -> list[int]:
    data = row.get(axis); 
    if not isinstance(data, dict): raise ValueError("native trace lacks limiter inputs")
    signs, left = _flat(data.get("slope_sign")), _flat(data.get("choose_left"))
    if len(signs)!=6 or len(left)!=6 or any(type(s)is not int or s not in (-1,0,1) for s in signs) or any(type(v)is not bool for v in left):
        raise ValueError("native limiter trace must have six signed choices and bool selectors")
    return [0 if s == 0 else (1 if l else 2) for s, l in zip(signs, left, strict=True)]

def audit_trace(native: list[dict[str, Any]], branch: list[dict[str, Any]], sides: tuple[int, int]) -> None:
    if len(native)!=36 or len(branch)!=36: raise ValueError("branch audit requires 36 analysis rows")
    for i, (src, row) in enumerate(zip(native, branch, strict=True)):
        if any(x.get(k)!=n for x in (src,row) for k,n in (("step",i//2),("stage",i%2))):
            raise ValueError("branch stage order malformed")
        if any(row.get(a)!=_choice(src,a) for a in ("x","y")):
            raise UnsupportedNormal("normal changed a native limiter-choice bin")
        qx, qy = _flat(src.get("qx_sign")), _flat(src.get("qy_sign"))
        rx, ry = row.get("qx_sign"), row.get("qy_sign")
        if not isinstance(rx,list) or not isinstance(ry,list) or (len(qx),len(qy),len(rx),len(ry))!=(24,25,24,25):
            raise ValueError("face-sign trace layout malformed")
        if any(type(v)is not int or v not in (-1,0,1) for v in qx+qy+rx+ry): raise ValueError("invalid face sign")
        if qx[22]!=0 or qy[15]!=0 or any(v==0 for j,v in enumerate(qx) if j!=22) or any(v==0 for j,v in enumerate(qy) if j!=15):
            raise ValueError("native trace must have only the selected zero faces")
        if (any(qx[j]!=rx[j] for j in range(24) if j!=22) or any(qy[j]!=ry[j] for j in range(25) if j!=15)
                or rx[22]!=sides[0] or ry[15]!=sides[1]):
            raise UnsupportedNormal("face signs differ from native other faces or requested orthant")

def _point(raw: Any) -> Fraction:
    if not isinstance(raw,list) or len(raw)!=4 or any(type(v)is not int for v in raw): raise ValueError("binary endpoint must be an mpmath tuple")
    sign,mantissa,exponent,bits=raw
    if sign not in (0,1) or mantissa<0 or bits<0 or mantissa.bit_length()!=bits:
        raise ValueError("binary endpoint malformed or nonfinite")
    return Fraction(-mantissa if sign else mantissa) * 2**exponent if exponent >= 0 else Fraction(-mantissa if sign else mantissa) / 2**-exponent
def _iv(raw: Any, name: str) -> tuple[Fraction, Fraction, list[int], list[int]]:
    if not isinstance(raw,dict) or set(raw)!={"lower","upper"}: raise ValueError(f"missing binary interval for {name}")
    lo, hi = _point(raw["lower"]), _point(raw["upper"])
    if lo>hi: raise ValueError(f"reversed interval for {name}")
    return lo, hi, raw["lower"], raw["upper"]

def interval(row: dict[str, Any], name: str):
    keys=("objective_mpi","J_binary") if name=="objective" else ("sigma_eta_mpi","sigma_eta_binary")
    return _iv(next((row[k] for k in keys if k in row),None),name)
def intersection(rows: list[tuple[Fraction, Fraction, list[int], list[int]]]):
    if not rows: return None
    lo, hi = max(rows, key=lambda r: r[0]), min(rows, key=lambda r: r[1])
    return (lo[0], hi[1], lo[2], hi[3]) if lo[0] <= hi[1] else None

def strict_orientation(left: tuple[Fraction, Fraction], right: tuple[Fraction, Fraction]) -> bool: return left[1] < 0 < right[0]
def audit_evaluation_set(rows: list[dict[str, Any]]) -> None:
    expected={(a,x,y) for a in (0,1) for x in (-1,1) for y in (-1,1)}; keys=[]
    for r in rows:
        a,s=r.get("normal_axis"),r.get("requested_sides")
        if type(a)is not int or a not in (0,1) or not isinstance(s,list) or len(s)!=2 or any(type(v)is not int or v not in (-1,1) for v in s) or r.get("sector_sides")!=s:
            raise ValueError("normal evaluation has unknown axis or malformed sector metadata")
        keys.append((a,*s))
    if len(keys)!=8 or len(set(keys))!=8 or set(keys)!=expected:
        raise ValueError("normal evaluations must cover each axis/orthant once")
def audit_fluxes(row: dict[str, Any], axis: int, scales: list[float]) -> None:
    vals, derivs = row.get("selected_flux_values_binary"), row.get("selected_flux_derivatives_binary")
    if not isinstance(vals,list) or not isinstance(derivs,list) or len(vals)!=2 or len(derivs)!=2: raise ValueError("reference omitted selected-flux intervals")
    flux = [_iv(v, "selected flux")[:2] for v in vals]
    rate = [_iv(v, "selected derivative")[:2] for v in derivs]
    if any(v!=(Fraction(0),Fraction(0)) for v in flux): raise ValueError("selected flux is not exact zero")
    active = Fraction.from_float(float(scales[axis]))
    if not rate[axis][0]<=active<=rate[axis][1] or rate[1-axis]!=(Fraction(0),Fraction(0)):
        raise ValueError("selected derivative differs from normal scale/inactive zero")
def primal_crosscheck(native: float, row: dict[str, Any]) -> dict[str, Any]:
    """Compare native J using a term-scaled FP64 gamma budget, without a unit floor."""
    lo,hi,*_ = interval(row,"objective"); j=Fraction.from_float(native)
    delta=Fraction(0) if lo<=j<=hi else min(abs(j-lo),abs(j-hi)); costs=[]
    for key in ("robust_cost_bounds", "prior_cost_bounds", "smooth_cost_bounds"):
        raw = row.get(key)
        if not isinstance(raw,list) or len(raw)!=2: raise ValueError(f"reference omitted {key}")
        bounds=[Fraction(Decimal(v)) for v in raw]
        if bounds[0]<0 or bounds[1]<bounds[0]: raise ValueError(f"{key} must bound a nonnegative term")
        costs.append(bounds[1])
    scale=abs(j)+max(abs(lo),abs(hi))+sum(costs); n=36*20*128+3*4*4+2*26+4*4*8+31*8
    ne=n*Fraction(1,2**52); budget=ne/(1-ne)*scale
    return {"passed":delta<=budget,"delta":float(delta),"budget":float(budget),"scale":float(scale),
            "operations":n,"delta_exact":str(delta),"budget_exact":str(budget)}

def grouped_normals(rows: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], str | None]:
    summaries,refusal=[],None
    for axis in (0,1):
        sides={}
        for side in (-1,1):
            sector=[r for r in rows if r["normal_axis"]==axis and r["requested_sides"][axis]==side]
            if len(sector)!=2 or {r["requested_sides"][1-axis] for r in sector}!={-1,1}:
                raise ValueError("normal side lacks unique evaluations from both other sectors")
            iv=intersection([interval(r,"sigma") for r in sector])
            if iv is None: refusal=refusal or f"axis {axis} derivative intervals disagree across sectors"; continue
            sides[side]=iv[:2]
            summaries.append({"normal_axis":axis,"side":side,"binary":{"lower":iv[2],"upper":iv[3]},
                              "exact_fraction_bounds":[str(iv[0]),str(iv[1])],"source_evaluations":[r["sector_sides"] for r in sector]})
        if len(sides)==2 and not strict_orientation(sides[-1],sides[1]):
            refusal=refusal or f"axis {axis} lacks strict left-negative/right-positive intervals"
    return summaries, refusal

def _write(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp=path.with_suffix(path.suffix+".tmp"); temp.write_text(json.dumps(payload,indent=2,sort_keys=True,allow_nan=False)+"\n"); temp.replace(path)

def run(output: Path) -> dict[str, Any]:
    if output.exists() or sha(INPUT)!=INPUT_SHA or sha(PLAN)!=PLAN_SHA or sha(PAIRED)!=PAIRED_SHA:
        raise ValueError("normal output must be fresh and input/report/plan pins unchanged")
    data, paired = json.loads(INPUT.read_text()), json.loads(PAIRED.read_text())
    sources = paired.get("source_after")
    if (not isinstance(sources,dict) or paired.get("source_before")!=sources or paired.get("input_before")!=paired.get("input_after")
            or data.get("input_identity")!=paired.get("input_before") or data.get("parameters_sha256")!=paired.get("parameters_sha256")
            or data.get("paired_report_sha256")!=PAIRED_SHA or paired.get("phase")!="finished"
            or paired.get("numerical_status")!="tangent_stationary_candidate" or paired.get("full_root_claim") is not False
            or paired.get("normal_validation")!="not_performed" or paired.get("response_validation")!="not_performed"
            or paired.get("selected_faces")!=[["x",3,4],["y",3,0]] or paired.get("normal_coordinates")!=[0.,0.]
            or data.get("tangent")!=paired.get("last_accepted_tangent")
            or data.get("native_analysis_trace")!=paired.get("final_trace",[])[:36]
            or data.get("native_objective")!=paired.get("final_objective")):
        raise ValueError("normal capture does not match the finished paired tangent report")
    runtime = {"python":platform.python_version(),"mpmath":mpmath.__version__}
    if runtime["python"]!=paired.get("runtime",{}).get("python"):
        raise ValueError("pure runtime Python differs from paired report provenance")
    reference.validate_projection(data["fixture"])
    paths = tuple(sorted(set(sources)|set(SOURCE_PATHS)))
    before = {name:sha(ROOT/name) for name in paths}
    if any(before[k]!=v for k,v in sources.items()):
        raise ValueError("paired producer sources differ from the captured root")
    rows, refusal = [], None
    try:
        for sx in (-1,1):
            for sy in (-1,1):
                for axis in (0,1):
                    row = reference.evaluate(data["fixture"],data["tangent"],axis,(sx,sy),dps=80)
                    if row.get("normal_axis")!=axis or row.get("sector_sides")!=[sx,sy]:
                        raise ValueError("reference returned mismatched sector metadata")
                    audit_trace(data["native_analysis_trace"],row.get("branch_choices",[]),(sx,sy))
                    audit_fluxes(row,axis,data["fixture"]["normal_scales"])
                    cmp = primal_crosscheck(data["native_objective"],row)
                    if not cmp["passed"]:
                        raise ValueError("independent J differs from native beyond its FP64 term-scale budget")
                    row.update(requested_sides=[sx,sy],native_objective_crosscheck=cmp)
                    rows.append(row)
    except UnsupportedNormal as error:
        refusal = str(error)
    if rows and refusal is None:
        audit_evaluation_set(rows)
    jout = intersection([interval(r,"objective") for r in rows]) if rows else None
    if rows and jout is None:
        refusal = refusal or "objective intervals across paired orthants do not overlap"
    normals = []
    if rows and refusal is None:
        normals, refusal = grouped_normals(rows)
    after = {name:sha(ROOT/name) for name in paths}
    if (after!=before or sha(INPUT)!=INPUT_SHA or sha(PLAN)!=PLAN_SHA or sha(PAIRED)!=PAIRED_SHA
            or platform.python_version()!=runtime["python"] or mpmath.__version__!=runtime["mpmath"]):
        raise ValueError("normal source/input/report/runtime changed during evaluation")
    payload = {"phase":"finished","numerical_status":"unsupported_normal" if refusal else "oriented_normal_intervals",
               "reason":refusal,"input_sha256":INPUT_SHA,"paired_report_sha256":PAIRED_SHA,"plan_sha256":PLAN_SHA,
               "source_before":before,"source_after":after,"input_identity_before":data["input_identity"],
               "input_identity_after":data["input_identity"],"runtime":runtime,"runtime_after":runtime,
               "normal_evaluations":rows,"objective_overlap_binary":None if jout is None else {"lower":jout[2],"upper":jout[3]},
               "normal_intervals":normals,"full_root_claim":False,"normal_minimum_claim":False,
               "response_validation":"not_performed","physical_validated":False}
    _write(output,payload); return payload

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output",type=Path,required=True)
    run(parser.parse_args().output)

"""Independent first-order interval reference at the paired point-FV face event.

Fixture contract (all numeric arrays are nested int/float/decimal-string values):
``background_dbz[4][5]``, ``psi_basis[5][5][6]``,
``projected_psi_basis[3][5][6]``, ``coefficient_limits[5]``,
``normal_weights[2][5]``, ``normal_scales[2]``, transform scalars
``floor_dbz``, ``transform_scale``, ``transform_epsilon``, ``increment_ratio``,
``echo_floor``, ``echo_exponent_factor``, ``dbz_log_factor``, ``growth_limit``,
``substeps``, ``dt``, ``area``, ``boundary_echo[2*substeps][2][4][edge]``,
``point_dbz[3][4]``, ``std_dbz[3][4]``, ``quality_weight[3][4]``,
``coordinates[4][2]``, symmetric ``whitener[4][4]``, ``robust_delta``, ``smooth_weight``,
``smooth_left_index``, ``smooth_right_index``, and ``smooth_physical_weight``.

This evaluates directional derivatives only. It is neither an optimizer nor a
normal-minimum/response certificate, and imports no production model code.
"""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from typing import Any

from examples.weather_scenarios import fv_active_face_normal_reference as normal
from examples.weather_scenarios import fv_slice_precision_reference as reference


_W_X = (1.0, 0.0, 4.0, -3.5, 16.0)
_W_Y = (0.0, -1.0, -3.0, -0.5, -3.0)
_KEEP_PAIR = (2, 3, 4)


class NormalReferenceRefusal(ValueError):
    """A supported strict-domain or interval branch could not be certified."""


def _certify(comparison: bool | None) -> bool:
    try:
        return reference._decide(comparison)
    except ValueError as error:
        raise NormalReferenceRefusal(str(error)) from error


@dataclass(frozen=True, eq=False)
class SectorEventJet(normal.IntervalJet):
    """Exact-zero face flux whose selected sector is explicit per event."""

    sector_sign: int = 1

    def __post_init__(self) -> None:
        if self.sector_sign not in (-1, 1) or not normal._is_exact_zero(self.value):
            raise ValueError("sector event must be an exact zero with sign +/-1")

    def _order(self, other: Any) -> int:
        right = self._coerce(other)
        greater = self.value > right.value
        if greater is True:
            return 1
        less = self.value < right.value
        if less is True:
            return -1
        equal = self.value == right.value
        if equal is True and normal._is_exact_zero(self.value):
            if isinstance(right, SectorEventJet):
                raise NormalReferenceRefusal("cannot order two independent tagged events")
            if right.event or not normal._is_exact_zero(right.derivative):
                raise NormalReferenceRefusal("selected event ties a nonconstant untagged zero")
            return self.sector_sign
        if equal is True:
            raise NormalReferenceRefusal("untagged nonsmooth tie in interval comparison")
        raise NormalReferenceRefusal("interval arithmetic cannot decide a branch comparison")


@dataclass(frozen=True, eq=False)
class _SectorZeroJet(normal.IntervalJet):
    """Zero sentinel that lets builtin max/min inspect a tagged event from either side."""

    def __gt__(self, other: Any) -> bool:
        if isinstance(other, SectorEventJet) and normal._is_exact_zero(other.value):
            return other.sector_sign < 0
        return self._order(other) > 0

    def __lt__(self, other: Any) -> bool:
        if isinstance(other, SectorEventJet) and normal._is_exact_zero(other.value):
            return other.sector_sign > 0
        return self._order(other) < 0


class _SectorJetMath(normal._JetMath):
    @property
    def zero(self) -> _SectorZeroJet:
        return _SectorZeroJet(self.context.zero, self.context.zero, self.side)


def _fraction(value: object) -> Fraction:
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise TypeError("fixture numbers must be int, float, or decimal strings")
    return Fraction.from_float(float(value)) if isinstance(value, float) else Fraction(value)


def _matrix(values: Any, rows: int, columns: int, name: str) -> list[list[Any]]:
    if (not isinstance(values, (list, tuple)) or len(values) != rows
            or any(not isinstance(row, (list, tuple)) or len(row) != columns for row in values)):
        raise ValueError(f"{name} must have shape [{rows},{columns}]")
    return [list(row) for row in values]


def _basis(values: Any, count: int, name: str) -> list[list[list[Any]]]:
    if not isinstance(values, (list, tuple)) or len(values) != count:
        raise ValueError(f"{name} must contain {count} modes")
    return [_matrix(_matrix(mode, 5, 6, name), 5, 6, name) for mode in values]


def validate_projection(fixture: dict[str, Any]) -> tuple[list[Any], list[Any]]:
    """Check captured weights and the paired projection in exact rationals."""
    basis = _basis(fixture["psi_basis"], 5, "psi_basis")
    paired = _basis(fixture["projected_psi_basis"], 3, "projected_psi_basis")
    b = [[[ _fraction(value) for value in row] for row in mode] for mode in basis]
    p = [[[ _fraction(value) for value in row] for row in mode] for mode in paired]
    wx, wy = tuple(map(_fraction, _W_X)), tuple(map(_fraction, _W_Y))
    captured_weights = fixture["normal_weights"]
    if not isinstance(captured_weights, (list, tuple)) or len(captured_weights) != 2:
        raise ValueError("normal_weights must contain the two pinned five-entry rows")
    if (tuple(map(_fraction, captured_weights[0])) != wx
            or tuple(map(_fraction, captured_weights[1])) != wy):
        raise ValueError("captured normal weights differ from the pinned paired rows")
    for k, mode in enumerate(b):
        if mode[4][4] - mode[3][4] != wx[k]:
            raise ValueError("psi basis q_x[3,4] weights differ from the pinned row")
        if -(mode[3][1] - mode[3][0]) != wy[k]:
            raise ValueError("psi basis q_y[3,0] weights differ from the pinned row")
    for i, k in enumerate(_KEEP_PAIR):
        for r in range(5):
            for c in range(6):
                # The pivot block is diag(1,-1), so eliminating both pivot
                # coefficients gives this exact rational basis projection.
                expected = (b[k][r][c] - wx[k] / wx[0] * b[0][r][c]
                            - wy[k] / wy[1] * b[1][r][c])
                if p[i][r][c] != expected:
                    raise ValueError("paired projected basis differs from the pinned rational formula")
        if p[i][3][0] != p[i][3][1] or p[i][4][4] != p[i][3][4]:
            raise ValueError("second projection did not preserve both exact selected zeros")
    limits = fixture["coefficient_limits"]
    if not isinstance(limits, (list, tuple)) or len(limits) != 5:
        raise ValueError("coefficient_limits must have length five")
    limit_f = tuple(map(_fraction, limits))
    if any(value <= 0 for value in limit_f):
        raise ValueError("coefficient limits must be positive")
    normal_scales = fixture["normal_scales"]
    if not isinstance(normal_scales, (list, tuple)) or len(normal_scales) != 2:
        raise ValueError("normal_scales must contain qx and qy scales")
    scales = tuple(map(_fraction, normal_scales))
    expected_scales = (abs(wx[0]) * limit_f[0], abs(wy[1]) * limit_f[1])
    if scales != expected_scales or scales != (_fraction(0.11), _fraction(0.08)):
        raise ValueError("paired face scales must match the original pivot rows and (.11,.08)")
    return list(wx), list(wy)


def _paired_projected_basis(fixture: dict[str, Any], mp: _SectorJetMath):
    return [reference._grid(mode, 5, 6, mp, "projected_psi_basis")
            for mode in fixture["projected_psi_basis"]]


def _selected_flux_binary(qx: SectorEventJet, qy: SectorEventJet) -> dict[str, list[dict[str, list[int]]]]:
    return {
        "selected_flux_values_binary": [normal._mpi(qx.value), normal._mpi(qy.value)],
        "selected_flux_derivatives_binary": [normal._mpi(qx.derivative), normal._mpi(qy.derivative)],
    }


def _validate_point_weights(std: list[list[normal.IntervalJet]],
                            quality: list[list[normal.IntervalJet]], mp: _SectorJetMath) -> None:
    if any(not _certify(value > 0) for row in std for value in row):
        raise ValueError("point observation standard deviations must be positive")
    if any(not _certify(value > 0) for row in quality for value in row):
        raise ValueError("point quality weights must be positive")
    # These are fixed fixture scalars. Check the closed upper bound on their
    # primal intervals directly; do not ask a directional jet to resolve a tie.
    if any(not _certify(value.value <= mp.context.one) for row in quality for value in row):
        raise ValueError("point quality weights must not exceed one")


def _point_samples(field: list[list[Any]], coordinates: list[list[Any]], mp: _SectorJetMath):
    h, w = len(field), len(field[0])
    result = []
    for row, column in coordinates:
        r, c = mp.context.mpf(row), mp.context.mpf(column)
        if not (_certify(r > 0) and _certify(r < h - 1)
                and _certify(c > 0) and _certify(c < w - 1)):
            raise NormalReferenceRefusal("bilinear observation point leaves the strict interior stencil")
        row_fraction, column_fraction = _fraction(row), _fraction(column)
        i = row_fraction.numerator // row_fraction.denominator
        j = column_fraction.numerator // column_fraction.denominator
        fr, fc = r - i, c - j
        result.append(field[i][j] * (1-fr) * (1-fc) + field[i][j+1] * (1-fr) * fc
                      + field[i+1][j] * fr * (1-fc) + field[i+1][j+1] * fr * fc)
    return result


def _classify_interval_failure(error: ValueError) -> NormalReferenceRefusal | None:
    message = str(error)
    if any(token in message for token in (
        "interval arithmetic could not certify", "interval arithmetic cannot decide",
        "event-side derivative sign is interval-ambiguous", "nonsmooth tie",
    )):
        return NormalReferenceRefusal(message)
    return None


def _euler_minmod(*args: Any, **kwargs: Any):
    try:
        return reference._euler_minmod(*args, **kwargs)
    except ValueError as error:
        refusal = _classify_interval_failure(error)
        if refusal is None:
            raise
        raise refusal from error


def evaluate(
    fixture: dict[str, Any], tangent: list[float | str], normal_axis: int,
    sides: tuple[int, int], dps: int = 80,
) -> dict[str, Any]:
    """Evaluate J and one normal derivative in one of the four paired sectors.

    ``normal_axis=0`` differentiates the qx[3,4] coordinate; ``1`` differentiates
    qy[3,0]. ``sides=(sx,sy)`` chooses the strict sector at both exact-zero faces.
    """
    if sides[0] not in (-1, 1) or sides[1] not in (-1, 1):
        raise ValueError("sector sides must each be -1 or +1")
    if normal_axis not in (0, 1) or len(tangent) != 24:
        raise ValueError("normal_axis must be 0/1 and tangent must have length 24")
    if type(dps) is not int or dps < 30:
        raise ValueError("dps must be an integer of at least 30")
    validate_projection(fixture)
    with reference._arithmetic(dps, True) as iv:
        mp = _SectorJetMath(iv, 1)
        z = mp.zero
        eta_x = normal._jet(iv.zero, 1, iv.one if normal_axis == 0 else iv.zero)
        eta_y = normal._jet(iv.zero, 1, iv.one if normal_axis == 1 else iv.zero)
        tangent_values = [reference._mp(value, mp) for value in tangent]
        tangent_jets = [normal._jet(value, 1) for value in tangent_values]
        limits = [reference._mp(value, mp) for value in fixture["coefficient_limits"]]
        wx = [reference._mp(value, mp) for value in _W_X]
        wy = [reference._mp(value, mp) for value in _W_Y]
        alpha = {k: limits[k] * mp.tanh(tangent_jets[20 + k - 2]) for k in (2, 3, 4)}
        alpha0 = (reference._mp(fixture["normal_scales"][0], mp) * eta_x
                  - mp.fsum(wx[k] * alpha[k] for k in (1, 2, 3, 4) if k in alpha)) / wx[0]
        alpha1 = (reference._mp(fixture["normal_scales"][1], mp) * eta_y
                  - mp.fsum(wy[k] * alpha[k] for k in (2, 3, 4))) / wy[1]
        ratio0, ratio1 = alpha0 / limits[0], alpha1 / limits[1]
        if not (_certify(ratio0 > -1) and _certify(ratio0 < 1)
                and _certify(ratio1 > -1) and _certify(ratio1 < 1)):
            raise NormalReferenceRefusal("paired lift leaves an original strict coefficient domain")
        pivot0, pivot1 = mp.atanh(ratio0), mp.atanh(ratio1)
        original_control = (tangent_jets[:20] + [pivot0, pivot1]
                            + tangent_jets[20:23] + [tangent_jets[23]])

        height, width = 4, 5
        background = reference._grid(fixture["background_dbz"], height, width, mp, "background_dbz")
        floor_dbz = reference._mp(fixture["floor_dbz"], mp)
        transform_scale = reference._mp(fixture["transform_scale"], mp)
        epsilon = reference._mp(fixture["transform_epsilon"], mp)
        increment_ratio = reference._mp(fixture["increment_ratio"], mp)
        echo_floor = reference._mp(fixture["echo_floor"], mp)
        echo_factor = reference._mp(fixture["echo_exponent_factor"], mp)
        dbz_factor = reference._mp(fixture["dbz_log_factor"], mp)
        echo = []
        for i in range(height):
            row = []
            for j in range(width):
                offset = (background[i][j] - floor_dbz) / transform_scale
                if not _certify(offset >= epsilon):
                    offset = epsilon
                latent = offset + mp.log(-mp.expm1(-offset))
                try:
                    softplus = reference._softplus(
                        latent + increment_ratio * tangent_jets[i * width + j], mp)
                except ValueError as error:
                    refusal = _classify_interval_failure(error)
                    if refusal is None:
                        raise
                    raise refusal from error
                analyzed = floor_dbz + transform_scale * softplus
                row.append(echo_floor * mp.expm1(echo_factor * (analyzed - floor_dbz)))
            echo.append(row)

        basis = _paired_projected_basis(fixture, mp)
        original_basis = [reference._grid(mode, 5, 6, mp, "psi_basis") for mode in fixture["psi_basis"]]
        scale_x = reference._mp(fixture["normal_scales"][0], mp)
        scale_y = reference._mp(fixture["normal_scales"][1], mp)
        psi = [[mp.fsum(alpha[k + 2] * basis[k][i][j] for k in range(3))
                + scale_x * eta_x * original_basis[0][i][j] / wx[0]
                + scale_y * eta_y * original_basis[1][i][j] / wy[1]
                for j in range(width + 1)] for i in range(height + 1)]
        qx = [[psi[i + 1][j] - psi[i][j] for j in range(width + 1)] for i in range(height)]
        qy = [[-(psi[i][j + 1] - psi[i][j]) for j in range(width)] for i in range(height + 1)]
        qx[3][4] = SectorEventJet((scale_x * eta_x).value,
                                  (scale_x * eta_x).derivative, 1, True, sides[0])
        qy[3][0] = SectorEventJet((scale_y * eta_y).value,
                                  (scale_y * eta_y).derivative, 1, True, sides[1])

        growth_limit = reference._mp(fixture["growth_limit"], mp)
        growth = growth_limit * mp.tanh(tangent_jets[23])
        if not _certify(growth > 0):
            raise NormalReferenceRefusal("normal reference requires the fixed positive-growth branch")
        substeps = fixture["substeps"]
        if type(substeps) is not int or substeps < 1:
            raise ValueError("substeps must be a positive integer")
        growth_factor = mp.exp(growth / substeps)
        dt, area = reference._mp(fixture["dt"], mp), reference._mp(fixture["area"], mp)
        boundaries = fixture["boundary_echo"]
        if not isinstance(boundaries, (list, tuple)) or len(boundaries) != 2 * substeps:
            raise ValueError("boundary_echo must cover two intervals of fixed substeps")
        if not (_certify(dt > 0) and _certify(area > 0)):
            raise ValueError("time step and cell area must be positive")
        frames = [echo]
        trace: list[dict[str, Any]] = []
        for step, step_edges in enumerate(boundaries):
            if len(step_edges) != 2 or any(len(stage) != 4 for stage in step_edges):
                raise ValueError("boundary_echo entries must have [stage][left,right,bottom,top]")
            edges = [[[reference._mp(value, mp) for value in edge] for edge in stage]
                     for stage in step_edges]
            if any(len(edges[stage][edge]) != (height if edge < 2 else width)
                   for stage in range(2) for edge in range(4)):
                raise ValueError("boundary edge lengths do not match the fixed 4x5 profile")
            grown = [[value * growth_factor for value in row] for row in echo]
            grown_edges = [[value * growth_factor for value in edge] for edge in edges[0]]
            stage1 = _euler_minmod(grown, qx, qy, grown_edges, dt, area,
                                   step, 0, trace, mp)
            stage2 = _euler_minmod(stage1, qx, qy, edges[1], dt, area,
                                   step, 1, trace, mp)
            echo = [[(grown[i][j] + stage2[i][j]) / 2 for j in range(width)]
                    for i in range(height)]
            if (step + 1) % substeps == 0:
                frames.append(echo)
        predicted_dbz = [[floor_dbz + dbz_factor * mp.log1p(value / echo_floor)
                          for row in frame for value in row] for frame in frames]

        coordinates = _matrix(fixture["coordinates"], 4, 2, "coordinates")
        observations = _matrix(fixture["point_dbz"], 3, 4, "point_dbz")
        std = _matrix(fixture["std_dbz"], 3, 4, "std_dbz")
        quality = _matrix(fixture["quality_weight"], 3, 4, "quality_weight")
        whitener = _matrix(fixture["whitener"], 4, 4, "whitener")
        if any(_fraction(whitener[i][j]) != _fraction(whitener[j][i])
               for i in range(4) for j in range(4)):
            raise ValueError("captured native point whitener must be exactly symmetric")
        obs_mp = [[reference._mp(value, mp) for value in row] for row in observations]
        std_mp = [[reference._mp(value, mp) for value in row] for row in std]
        quality_mp = [[reference._mp(value, mp) for value in row] for row in quality]
        _validate_point_weights(std_mp, quality_mp, mp)
        delta = reference._mp(fixture["robust_delta"], mp)
        if not _certify(delta > 0):
            raise ValueError("robust_delta must be positive")
        residuals = []
        for t in range(3):
            samples = _point_samples([predicted_dbz[t][i * width:(i + 1) * width]
                                      for i in range(height)], coordinates, mp)
            residuals.append([mp.sqrt(quality_mp[t][k]) * (samples[k] - obs_mp[t][k]) / std_mp[t][k]
                              for k in range(4)])
        white = [[mp.fsum(reference._mp(whitener[i][j], mp) * residuals[t][j]
                          for j in range(4)) for i in range(4)] for t in range(3)]
        robust = mp.fsum(value**2 / (mp.sqrt(1 + (value / delta)**2) + 1)
                         for row in white for value in row)
        prior = mp.fsum(value**2 for value in original_control) / 2
        smooth_weight = reference._mp(fixture["smooth_weight"], mp)
        left, right = fixture["smooth_left_index"], fixture["smooth_right_index"]
        smooth_weights = fixture["smooth_physical_weight"]
        if not (len(left) == len(right) == len(smooth_weights)):
            raise ValueError("field-prior edge arrays must have equal lengths")
        smooth = z
        for i, j, weight in zip(left, right, smooth_weights, strict=True):
            if type(i) is not int or type(j) is not int or not (0 <= i < 20 and 0 <= j < 20):
                raise ValueError("smoothness edges must index the 20 field controls")
            difference = original_control[j] - original_control[i]
            smooth += smooth_weight * reference._mp(weight, mp) * difference**2 / 2
        objective = robust + prior + smooth
        return {
            "normal_axis": normal_axis, "sector_sides": list(sides),
            "objective_interval": mp.nstr(objective.value, n=dps),
            "sigma_eta_interval": mp.nstr(objective.derivative, n=dps),
            "objective_mpi": normal._mpi(objective.value),
            "sigma_eta_mpi": normal._mpi(objective.derivative),
            "J_binary": normal._mpi(objective.value),
            "sigma_eta_binary": normal._mpi(objective.derivative),
            "objective_bounds": normal._bounds(objective.value, dps),
            "sigma_eta_bounds": normal._bounds(objective.derivative, dps),
            "interval_bound_representation": "mpmath.iv._mpi exact binary endpoint tuples are authoritative",
            "selected_flux_values": [mp.nstr(qx[3][4].value, n=dps), mp.nstr(qy[3][0].value, n=dps)],
            "selected_flux_derivatives": [mp.nstr(qx[3][4].derivative, n=dps),
                                          mp.nstr(qy[3][0].derivative, n=dps)],
            **_selected_flux_binary(qx[3][4], qy[3][0]),
            "robust_cost_interval": mp.nstr(robust.value, n=dps),
            "prior_cost_interval": mp.nstr(prior.value, n=dps),
            "smooth_cost_interval": mp.nstr(smooth.value, n=dps),
            "robust_cost_bounds": normal._bounds(robust.value, dps),
            "prior_cost_bounds": normal._bounds(prior.value, dps),
            "smooth_cost_bounds": normal._bounds(smooth.value, dps),
            "branch_choices": trace,
            "scope": "directional interval derivative at one fixed paired-zero point; no optimizer or normal-minimum claim",
        }

